def parse_duration(text: str) -> float:
    if not text or text[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    text = text[1:]  # Remove 'P'

    # Check if we have a time component
    if 'T' in text:
        parts = text.split('T')
        if len(parts) != 2:
            raise ValueError("Invalid 'T' placement")
        date_part, time_part = parts
        if not time_part:
            raise ValueError("'T' must be followed by at least one time component")
    else:
        date_part = text
        time_part = ""

    # If text is empty or only contains 'T', it's invalid
    if not date_part and not time_part:
        raise ValueError("At least one component must be present")

    total_seconds = 0.0

    # Parse date part (weeks or days)
    if date_part:
        if 'Y' in date_part or 'M' in date_part:
            raise ValueError("Years and months are not supported")

        if 'W' in date_part:
            # Week format: P<n>W
            if 'D' in date_part:
                raise ValueError("Cannot mix weeks and days")

            w_idx = date_part.index('W')
            if w_idx != len(date_part) - 1:
                raise ValueError("'W' must be at the end of date part")

            try:
                weeks = float(date_part[:w_idx])
            except ValueError:
                raise ValueError("Invalid week value")

            if weeks < 0:
                raise ValueError("Duration values must be non-negative")

            total_seconds += weeks * 7 * 86400

        elif 'D' in date_part:
            # Day format: P<n>D
            d_idx = date_part.index('D')
            if d_idx != len(date_part) - 1:
                raise ValueError("'D' must be at the end of date part")

            try:
                days = float(date_part[:d_idx])
            except ValueError:
                raise ValueError("Invalid day value")

            if days < 0:
                raise ValueError("Duration values must be non-negative")

            total_seconds += days * 86400

        elif date_part:
            raise ValueError("Date part must contain 'W' or 'D'")

    # Parse time part (hours, minutes, seconds)
    if time_part:
        remaining = time_part

        # Hours
        if 'H' in remaining:
            h_idx = remaining.index('H')
            try:
                hours = float(remaining[:h_idx])
            except ValueError:
                raise ValueError("Invalid hour value")
            if hours < 0:
                raise ValueError("Duration values must be non-negative")
            total_seconds += hours * 3600
            remaining = remaining[h_idx + 1:]

        # Minutes
        if 'M' in remaining:
            m_idx = remaining.index('M')
            try:
                minutes = float(remaining[:m_idx])
            except ValueError:
                raise ValueError("Invalid minute value")
            if minutes < 0:
                raise ValueError("Duration values must be non-negative")
            total_seconds += minutes * 60
            remaining = remaining[m_idx + 1:]

        # Seconds
        if 'S' in remaining:
            s_idx = remaining.index('S')
            try:
                seconds = float(remaining[:s_idx])
            except ValueError:
                raise ValueError("Invalid second value")
            if seconds < 0:
                raise ValueError("Duration values must be non-negative")
            total_seconds += seconds
            remaining = remaining[s_idx + 1:]

        if remaining:
            raise ValueError("Invalid characters in time part")

    return total_seconds
